contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address[] memory tos, uint[] memory vals) public payable {
        bool reverted;
        bool ret;

        if (tos.length != vals.length || tos.length == 0 || msg.sender != address(this)) {
            return;
        }

        try c.transfer(tos, vals) returns (bool r) {
            ret = r;
            reverted = false;
        } catch {
            ret = false;
            reverted = true;
        }

        bool ok = true;
        for (uint i = 0; i < vals.length; i++) {
            if (vals[i] == 0) { ok = false; break; }
            if ((vals[i] * 1e18) / vals[i] != 1e18) { ok = false; break; }
        }

        assert(reverted == !ok || (reverted == false && ret == true));
    }

    receive() external payable {}
}

