contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address[] memory tos, uint[] memory vs) public payable {
        uint len = tos.length;
        uint vlen = vs.length;
        bool shapeOk = (len > 0) && (vlen >= len);
        bool fromOk = (msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Note: msg.sender for this call is the test contract, not the required address,
        // so the precondition below only holds conceptually; the property is stated as
        // a general conditional on the caller being the required address.
        require(fromOk, "caller not the required address");

        bool reverted;
        bool returned;
        try c.transfer(tos, vs) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        // General rule: if the call completes (does not revert), it must have been made with
        // a non-empty tos array, vs must supply at least as many values as tos, and it must
        // return true. Conversely, if tos is empty, the call must revert.
        assert(
            (reverted == false) == (shapeOk && true)
            && (reverted == false ? returned == true : true)
            && (len == 0 ? reverted : true)
        );
    }
    receive() external payable {}
}

